import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import { calendarSyncList, calendarSyncSyncNowCreate } from 'products/customer_analytics/frontend/generated/api'
import type { CalendarSyncStatusApi } from 'products/customer_analytics/frontend/generated/api.schemas'

const POLL_INTERVAL_MS = 5000

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface calendarSyncLogicValues {
    currentTeamId: number | null // teamLogic
    statusByIntegrationId: Record<number, CalendarSyncStatusApi>
    statuses: CalendarSyncStatusApi[]
    statusesLoading: boolean
    triggeringIntegrationIds: number[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface calendarSyncLogicActions {
    loadStatuses: () => any
    loadStatusesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadStatusesSuccess: (
        statuses: CalendarSyncStatusApi[],
        payload?: any
    ) => {
        statuses: CalendarSyncStatusApi[]
        payload?: any
    }
    syncNow: (integrationId: number) => {
        integrationId: number
    }
    triggerFinished: (integrationId: number) => {
        integrationId: number
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface calendarSyncLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        statusByIntegrationId: (statuses: CalendarSyncStatusApi[]) => Record<number, CalendarSyncStatusApi>
    }
}

export type calendarSyncLogicType = MakeLogicType<
    calendarSyncLogicValues,
    calendarSyncLogicActions,
    Record<string, any>,
    calendarSyncLogicMeta
>

export const calendarSyncLogic = kea<calendarSyncLogicType>([
    path(['scenes', 'customerAnalytics', 'configuration', 'calendarSyncLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    actions({
        syncNow: (integrationId: number) => ({ integrationId }),
        triggerFinished: (integrationId: number) => ({ integrationId }),
    }),
    loaders(({ values }) => ({
        statuses: [
            [] as CalendarSyncStatusApi[],
            {
                loadStatuses: async (): Promise<CalendarSyncStatusApi[]> => {
                    try {
                        return [...(await calendarSyncList(String(values.currentTeamId)))]
                    } catch (error) {
                        posthog.captureException(error as Error, { scope: 'calendarSyncLogic.loadStatuses' })
                        return values.statuses
                    }
                },
            },
        ],
    })),
    reducers({
        triggeringIntegrationIds: [
            [] as number[],
            {
                syncNow: (state, { integrationId }) =>
                    state.includes(integrationId) ? state : [...state, integrationId],
                triggerFinished: (state, { integrationId }) => state.filter((id) => id !== integrationId),
            },
        ],
    }),
    selectors({
        statusByIntegrationId: [
            (s) => [s.statuses],
            (statuses: CalendarSyncStatusApi[]): Record<number, CalendarSyncStatusApi> =>
                Object.fromEntries(statuses.map((status) => [status.integration_id, status])),
        ],
    }),
    listeners(({ actions, values }) => ({
        // A sync in flight self-perpetuates the status poll; the breakpoint cancels it on unmount.
        loadStatusesSuccess: async (_, breakpoint) => {
            if (values.statuses.some((status) => status.is_syncing)) {
                await breakpoint(POLL_INTERVAL_MS)
                actions.loadStatuses()
            }
        },
        syncNow: async ({ integrationId }) => {
            try {
                const result = await calendarSyncSyncNowCreate(String(values.currentTeamId), {
                    integration_id: integrationId,
                })
                if (result.status === 'already_running') {
                    lemonToast.info('A sync for this calendar is already running')
                } else {
                    lemonToast.success('Calendar sync started. New meetings appear in a few minutes.')
                }
            } catch (error) {
                posthog.captureException(error as Error, { scope: 'calendarSyncLogic.syncNow' })
                lemonToast.error('Failed to start the calendar sync')
            } finally {
                actions.triggerFinished(integrationId)
                actions.loadStatuses()
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadStatuses()
    }),
])
